package com.surprising.aeron.service.state;
import com.surprising.aeron.protocol.*;
import com.surprising.product.api.ProductLine;
import java.util.concurrent.TimeUnit;
import org.openjdk.jmh.annotations.*;
@State(Scope.Thread) @BenchmarkMode(Mode.AverageTime) @OutputTimeUnit(TimeUnit.NANOSECONDS)
@Fork(value=1,jvmArgsAppend={"-Xms256m","-Xmx256m","-XX:+UseG1GC","--add-exports=java.base/jdk.internal.misc=ALL-UNNAMED"})
public class AccountWriteSimplificationBenchmark {
 private TradingRuntimeState runtime; private int asset; private boolean increase;
 @Setup public void setup() {
  var ids=new RuntimeIdentityRegistry();
  runtime=RuntimeStateProjector.project(TradingCoreState.empty(ProductLine.SPOT),ids);
  RuntimeAccountStateTransitions.adjustBalance(runtime,ids,7,new BalanceAdjustmentCommand("USDT",1_000_000_000_000L));
  asset=ids.assetId("USDT"); runtime.clearChangedKeys();
 }
 @Benchmark public long adjustExisting() {
  increase=!increase;
  RuntimeAccountStateTransitions.adjustAccountBalance(runtime,7,asset,increase?1:-1);
  long value=runtime.balance(7,asset).availableUnits(); runtime.clearChangedKeys(); return value;
 }
 @Benchmark public long debitExisting() {
  RuntimeAccountStateTransitions.debitTransferAccount(runtime,7,asset,1);
  long value=runtime.balance(7,asset).availableUnits(); runtime.clearChangedKeys(); return value;
 }
 @TearDown public void close(){runtime.close();}
}
